  /**
   * Test that the basic conversion from FileMetaData to ParquetMetadata works.
   */
  @org.junit.jupiter.api.Test
  public void testBasicConversion() throws IOException {
    // Create a simple schema
    SchemaElement schemaElement = new SchemaElement("message")
        .setType(Type.GROUP)
        .setNum_children(1);
    SchemaElement int32Element = new SchemaElement("int32_col")
        .setType(Type.INT32)
        .setRepetition_type(org.apache.parquet.format.FieldRepetitionType.REQUIRED);
    List<SchemaElement> schema = new ArrayList<>();
    schema.add(schemaElement);
    schema.add(int32Element);

    // Create FileMetaData
    FileMetaData fileMetaData = new FileMetaData();
    fileMetaData.setSchema(schema);
    fileMetaData.setNum_rows(1000L);
    fileMetaData.setCreated_by("test-writer");

    // Create a row group with a column chunk
    RowGroup rowGroup = new RowGroup();
    rowGroup.setNum_rows(500L);
    rowGroup.setTotal_byte_size(1000L);

    ColumnChunk columnChunk = new ColumnChunk();
    columnChunk.setFile_path("/path/to/file.parquet");
    columnChunk.setFile_offset(0L);

    ColumnMetaData columnMetaData = new ColumnMetaData();
    columnMetaData.setPath_in_schema("int32_col");
    columnMetaData.setType(Type.INT32);
    columnMetaData.setEncoding_list(new ArrayList<>());
    columnMetaData.setNum_values(500L);
    columnMetaData.setTotal_compressed_size(100L);
    columnMetaData.setTotal_uncompressed_size(200L);
    columnMetaData.setStatistics(new Statistics());

    columnChunk.setMeta_data(columnMetaData);
    rowGroup.setColumns(List.of(columnChunk));

    fileMetaData.setRow_groups(List.of(rowGroup));

    // Convert
    ParquetMetadata result = converter.fromParquetMetadata(fileMetaData);

    // Verify
    assertThat(result).isNotNull();
    assertThat(result.getFileMetaData()).isNotNull();
    assertThat(result.getFileMetaData().getSchema()).isNotNull();
    assertThat(result.getFileMetaData().getCreatedBy()).isEqualTo("test-writer");
    assertThat(result.getBlocks()).hasSize(1);

    BlockMetaData block = result.getBlocks().get(0);
    assertThat(block.getRowCount()).isEqualTo(500L);
    assertThat(block.getTotalByteSize()).isEqualTo(1000L);
    assertThat(block.getPath()).isEqualTo("/path/to/file.parquet");
    assertThat(block.getColumns()).hasSize(1);

    ColumnChunkMetaData column = block.getColumns().get(0);
    assertThat(column.getPath().toString()).isEqualTo("int32_col");
    assertThat(column.getType()).isEqualTo(PrimitiveTypeName.INT32);
  }

